    for r in [r_min, r_max]:
        row_marks = sorted([c for c in range(len(grid[r])) if grid[r][c] != bg])
        if len(row_marks) >= 2:
            for i in range(len(row_marks) - 1):
                for c in range(row_marks[i] + 1, row_marks[i+1]):
                    if o[r][c] == bg:
                        o[r][c] = 2

    # Vertical fill at edge columns c_min, c_max
    # Mark blocks: consecutive sequences of marks
    # Fill: from r_min to first mark, from last mark to r_max, between consecutive mark blocks
    for c in [c_min, c_max]:
        col_marks = sorted([r for r in range(len(grid)) if grid[r][c] != bg])
