        # Fill from last mark to r_max  
        last = col_marks[-1]
        for r in range(last + 1, r_max + 1):
            if o[r][c] == bg:
                o[r][c] = 2

        # Fill between consecutive mark blocks where gap >= 1
        # A "block" is consecutive marks; gaps between blocks get filled
        in_block = True
        for i in range(len(col_marks)):
            r = col_marks[i]
            if in_block:
                # Check if next is consecutive
                if i + 1 < len(col_marks) and col_marks[i+1] == r + 1:
