    # ================================================
    for r in [r_min, r_max]:
        row_marks_list = sorted(row_marks.get(r, []))
        if not row_marks_list:
            continue

        if complete:
            # Fill between adjacent marks
            for i in range(len(row_marks_list) - 1):
                for c in range(row_marks_list[i] + 1, row_marks_list[i+1]):
                    if o[r][c] == bg:
                        o[r][c] = 2
        else:
            # Need to determine fills from edge cols + between marks
            # For now, fill from c_min to first mark, between marks, from last mark to c_max
            for i in range(len(row_marks_list) - 1):
                for c in range(row_marks_list[i] + 1, row_marks_list[i+1]):
                    if o[r][c] == bg:
                        o[r][c] = 2

    return o

